<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">sudo</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ls</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /proc/</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">$SIDECAR_PID</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">/root/</span></span>
